"""Plot the Wolfire et al. (1995) comparison generated by test/test.out."""

import argparse
from functools import lru_cache
from pathlib import Path

import matplotlib

if __name__ == "__main__":
    matplotlib.use("Agg")

import matplotlib.pyplot as plt
import numpy as np

from plot_style import GRAY, PLOT_STYLE, SERIES_COLORS


PLOT_DIR = Path(__file__).resolve().parent
DENSITY_LABEL = r"$\log_{10}[n_{\rm H}/(\mathrm{cm}^{-3})]$"
PRESSURE_LABEL = r"$\log_{10}[n_{\rm H}T/(\mathrm{K\,cm}^{-3})]$"
# Zero-based column indices in the headerless PostProcessMap files.
RESULT_COLUMNS = {8: "T", 12: "n_H", 16: "n_e", 17: "n_HII", 18: "n_HI"}
Y_HE = 0.1  # n_He / n_H used for the mean molecular weight


def result_file(column=1e19, isrf=1.0, metallicity=1.0, *, abundances=None, x0=None):
    name = f"PostProcessMap_Nt{column:.1e}_ISRF{isrf:.1f}_Zs{metallicity:.1e}"
    if abundances is not None:
        carbon, oxygen = abundances
        name += f"_Ac{carbon:.1e}_Ao{oxygen:.1e}"
    if x0 is not None:
        name += f"_Xo{x0:.1f}"
    return name + ".dat"


REFERENCE = result_file()
PANELS = (
    (
        r"Column density (ISRF = 1, $Z=Z_\odot$)",
        [(result_file(column=10.0**exponent), rf"$N_{{\rm tot}}=10^{{{exponent}}}$ cm$^{{-2}}$")
         for exponent in (19, 18, 20)],
    ),
    (
        r"Metallicity ($N_{\rm tot}=10^{19}$ cm$^{-2}$, ISRF = 1)",
        [(result_file(metallicity=z), rf"$Z/Z_\odot={z:g}$")
         for z in (1, 0.01, 0.03, 0.1, 0.3, 3)],
    ),
    (
        r"Radiation field ($N_{\rm tot}=10^{19}$ cm$^{-2}$, $Z=Z_\odot$)",
        [(result_file(isrf=isrf), f"ISRF = {isrf:g}")
         for isrf in (1, 0.3, 0.5, 3, 10, 100, 1000)],
    ),
    (
        r"C and O abundances ($N_{\rm tot}=10^{19}$ cm$^{-2}$, ISRF = 1, $Z=Z_\odot$)",
        [(result_file(abundances=(carbon, oxygen)), rf"$A_{{\rm C}}={carbon:g}, A_{{\rm O}}={oxygen:g}$")
         for carbon, oxygen in ((1, 1), (0.1, 1), (0.5, 0.65), (1, 1.7), (0.5, 1))],
    ),
)
X0_VALUES = (1, 0.1, 10, 100, 1000)


class WolfireResults:
    """Reads PostProcessMap files from out/, results/ or the run directory itself."""

    def __init__(self, run_dir):
        self.run_dir = Path(run_dir)
        self.data_dir = next(
            (directory for directory in (self.run_dir / "out", self.run_dir / "results", self.run_dir)
             if (directory / REFERENCE).is_file()),
            None,
        )
        if self.data_dir is None:
            raise FileNotFoundError(f"No {REFERENCE} in {self.run_dir}")

    @lru_cache(maxsize=None)
    def __getitem__(self, filename):
        path = self.data_dir / filename
        if not path.is_file():
            raise FileNotFoundError(f"Missing comparison result {path}")
        columns = np.loadtxt(path, usecols=tuple(RESULT_COLUMNS), ndmin=2)
        return {name: columns[:, index] for index, name in enumerate(RESULT_COLUMNS.values())}

    def rejected(self):
        """Return the solver failures saved in rejected.tsv, or None when absent."""
        path = self.run_dir / "rejected.tsv"
        if not path.is_file():
            return None
        data = np.genfromtxt(path, names=True, delimiter="\t", dtype=None,
                             encoding="utf-8", ndmin=1, deletechars="")
        return np.sort(data, order=["case", "sample"])


def log10_positive(values):
    values = np.asarray(values, dtype=float)
    return np.log10(np.where(values > 0, values, np.nan))


def series_style(index):
    return {"color": SERIES_COLORS[index % len(SERIES_COLORS)], "lw": 2.2 if index == 0 else 1.3}


def plot_density_panels(results, quantity, ylabel, *, xlim, ylim=None, title=None):
    fig, axes = plt.subplots(2, 2, figsize=(11, 7.5), sharex=True, layout="constrained")
    if title:
        fig.suptitle(title)
    for ax, (panel_title, cases) in zip(axes.flat, PANELS):
        for index, (filename, label) in enumerate(cases):
            data = results[filename]
            ax.plot(log10_positive(data["n_H"]), quantity(data), label=label, **series_style(index))
        ax.set(title=panel_title, xlim=xlim, ylim=ylim)
        ax.legend(fontsize=8)
    for ax in axes[-1]:
        ax.set_xlabel(DENSITY_LABEL)
    fig.supylabel(ylabel)
    return fig


def plot_pressure(results):
    return plot_density_panels(
        results, lambda data: log10_positive(data["n_H"] * data["T"]), PRESSURE_LABEL,
        xlim=(-2, 3), ylim=(2, 6), title="Wolfire et al. (1995) thermal equilibrium pressure",
    )


def plot_hii_fraction(results):
    return plot_density_panels(
        results, lambda data: log10_positive(data["n_HII"] / data["n_H"]),
        r"$\log_{10}(n_{\rm HII}/n_{\rm H})$", xlim=(-3, 3), title="Ionized hydrogen fraction",
    )


def plot_hi_fraction(results):
    return plot_density_panels(
        results, lambda data: data["n_HI"] / data["n_H"],
        r"$n_{\rm HI}/n_{\rm H}$", xlim=(-3, 3), ylim=(0, 1.02), title="Neutral hydrogen fraction",
    )


def plot_x0_scaling(results):
    fig, ax = plt.subplots(figsize=(7, 4.5), layout="constrained")
    fig.suptitle(r"Pressure scaled by the radiation field $X_0$")
    for index, x0 in enumerate(X0_VALUES):
        data = results[result_file(isrf=x0, x0=x0)]
        scaled_density = data["n_H"] / x0
        ax.plot(log10_positive(scaled_density), log10_positive(scaled_density * data["T"]),
                label=rf"$X_0={x0:g}$", **series_style(index))
    ax.set(
        xlabel=r"$\log_{10}[(n_{\rm H}/X_0)/(\mathrm{cm}^{-3})]$",
        ylabel=r"$\log_{10}[(n_{\rm H}T/X_0)/(\mathrm{K\,cm}^{-3})]$",
        xlim=(-2, 3), ylim=(2, 6),
    )
    ax.legend(fontsize=8)
    return fig


def plot_mean_molecular_weight(results):
    models = (
        (REFERENCE, r"ISRF = 1, $Z/Z_\odot=1$"),
        (result_file(metallicity=0.1), r"ISRF = 1, $Z/Z_\odot=0.1$"),
        (result_file(isrf=10), r"ISRF = 10, $Z/Z_\odot=1$"),
    )
    mass_per_h = 1 + 4 * Y_HE
    fig, (ax_mu, ax_xe) = plt.subplots(2, 1, figsize=(7, 7), sharex=True, layout="constrained")
    fig.suptitle(r"Mean molecular weight · $N_{\rm tot}=10^{19}$ cm$^{-2}$")
    for index, (filename, label) in enumerate(models):
        data = results[filename]
        order = np.argsort(data["T"])
        temperature = data["T"][order]
        xe = (data["n_e"] / data["n_H"])[order]
        style = series_style(index)
        ax_mu.plot(temperature, mass_per_h / (1 + Y_HE + xe), label=label, **style)
        ax_xe.plot(temperature, xe, **style)

    for particles, label, line_style in (
        (1 + Y_HE, "Neutral", "--"),
        (2 + Y_HE, "H ionized, He neutral", "-."),
        (2 + 3 * Y_HE, "Fully ionized", ":"),
    ):
        mu_limit = mass_per_h / particles
        ax_mu.axhline(mu_limit, color=GRAY, ls=line_style, lw=1,
                      label=rf"{label}: $\mu={mu_limit:.2f}$")
    ax_mu.set(xscale="log", ylabel=r"Mean molecular weight $\mu$")
    ax_xe.set(xscale="log", yscale="log", xlabel=r"$T$ [K]", ylabel=r"Electron fraction $x_e$")
    ax_mu.legend(fontsize=8)
    return fig


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--run-dir", type=Path, default=PLOT_DIR.parent / "test" / "out" / "wolfire")
    parser.add_argument("--output-dir", type=Path, default=PLOT_DIR / "out" / "wolfire")
    args = parser.parse_args()
    try:
        results = WolfireResults(args.run_dir)
        args.output_dir.mkdir(parents=True, exist_ok=True)
        with plt.rc_context(PLOT_STYLE):
            for name, plot in (
                ("pressure.png", plot_pressure),
                ("x0_scaling.png", plot_x0_scaling),
                ("hii_fraction.png", plot_hii_fraction),
                ("hi_fraction.png", plot_hi_fraction),
                ("mean_molecular_weight.png", plot_mean_molecular_weight),
            ):
                fig = plot(results)
                fig.savefig(args.output_dir / name, dpi=180)
                plt.close(fig)
    except (OSError, ValueError) as error:
        parser.error(str(error))
    print(f"Wolfire et al. (1995) plots written to {args.output_dir}")


if __name__ == "__main__":
    main()
